// This file is generated by AI.

// 配音使用说明页: 渲染仓库内的 Markdown 文档。
//
// 性能注意: 说明文档含有较多表格与代码片段, 一旦被 React 反复重建就会明显卡顿。
// 因此这里 **只在挂载时把渲染结果写入 DOM 一次**, 之后 React 不再接触这段子树
// (用 ref + effect 而不是 `dangerouslySetInnerHTML`, 后者在每次重渲染时都会重新写入)。
// 解析结果本身也在模块级缓存, 保证 markdown 只解析一次。

import { marked } from 'marked';
import { useEffect, useRef } from 'react';

import { VOICE_GUIDE_MARKDOWN } from './guide';

let cachedHtml: string | null = null;

/** 解析并缓存说明文档的 HTML (模块级: 整个会话只解析一次) */
function guideHtml(): string {
  cachedHtml ??= marked.parse(VOICE_GUIDE_MARKDOWN, { async: false, gfm: true }) as string;
  return cachedHtml;
}

export function VoiceGuidePane() {
  const hostRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    // 内容来自仓库内固定的 Markdown 文案, 不含用户输入
    host.innerHTML = guideHtml();
  }, []);

  return (
    <div className="voice-guide">
      <div className="voice-guide-body" ref={hostRef} />
    </div>
  );
}
